-- Kokoelma- ja pelimuotosivujen copytekstit (12 sivua), Claude 2026-08-02.
-- Ajettu tuotantokantaan MCP:llä; tämä on seed-tallenne.
on conflict (slug) do update set kind=excluded.kind, name=excluded.name,
  seo_title=excluded.seo_title, seo_description=excluded.seo_description,
  learn=excluded.learn, updated_at=now();