insert into page_content (slug,kind,name,seo_title,seo_description,learn) values
('tv','collection','TV & Suoratoisto','TV-sarjojen tietovisat — kotimaiset ja Netflix-hitit','Testaa mitä muistat sarjoista: komediat, rikosdraamat, tosi-tv ja kotimaiset klassikot. Kymmenen kysymystä per visa, ilmaiseksi ja ilman rekisteröitymistä.','{"intro": "Sarja loppui kuukausia sitten, mutta muistatko enää mitä siinä oikeasti tapahtui? TV-kokoelmassa on visoja suoratoistohiteistä kotimaisiin klassikoihin — ja jokaisen kysymyksen jälkeen kerrotaan, mistä oli kyse.", "title": "TV-visat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Genre kerrallaan", "p": ["Kokoelma on jaettu genreihin: komedia, draama, rikosdraama, tosi-tv, animaatio ja scifi. Suurin osa visoista on komedioita ja draamoja, mikä kertoo aika hyvin siitä mitä Suomessa katsotaan.", "Genre-suodatin auttaa löytämään oman makusi. Jos etsit nimenomaan rikosdraamaa etkä jaksa selata koko katalogia, valitse se suoraan."]}, {"h": "Kotimaiset ja ulkomaiset", "p": ["Jokainen sarjavisa on merkitty joko kotimaiseksi tai ulkomaiseksi. Kotimaisesta päästä löytyvät ne sarjat, joiden repliikkejä siteerataan yhä kahvihuoneissa; ulkomaisesta päästä isot suoratoistonimet.", "Kotimaiset sarjat ovat oma lajinsa: niissä muistikuvat ovat usein tarkempia, koska sarjat katsottiin aikanaan koko perheen kesken eikä yhdeltä istumalta."]}, {"h": "Miten sarjavisa etenee", "p": ["Jokaisessa TV-kokoelman visassa on kymmenen kysymystä ja neljä vaihtoehtoa. Vastauksen jälkeen näet heti oliko se oikein ja saat lyhyen taustafaktan.", "Lopuksi näet tuloksesi ja voit haastaa kaverin samaan visaan. Kirjautumista ei tarvita eikä tulosta tallenneta minnekään."]}], "faq": [{"q": "Kuinka monta kysymystä TV-visassa on?", "a": "Kymmenen. Jokaisessa kysymyksessä on neljä vaihtoehtoa, joista yksi on oikein."}, {"q": "Onko visojen pelaaminen ilmaista?", "a": "On. Tietoniekan kaikki visat ovat ilmaisia eikä käyttäjätiliä tarvita."}, {"q": "Löytyykö kokoelmasta kotimaisia sarjoja?", "a": "Kyllä. Kotimaiset ja ulkomaiset sarjat ovat omina ryhminään, ja voit suodattaa kummankin erikseen."}, {"q": "Toimivatko visat puhelimella?", "a": "Toimivat. Tietoniekka on suunniteltu ensisijaisesti puhelimelle."}]}'::jsonb),
('urheilu','collection','Urheilu','Urheiluvisat — jääkiekko, jalkapallo, F1 ja muut lajit','Maajoukkueet, seurat, F1, tennis ja MM-kisat. Testaa urheilutietosi ilmaisilla visoilla — kymmenen kysymystä kerrallaan, ei rekisteröitymistä.','{"intro": "Urheilussa faktat ovat harvinaisen tarkkoja: vuosiluvut, maalimäärät ja mestaruudet joko muistetaan tai ei. Tämä kokoelma kokoaa yhteen lajit jääkiekosta golfiin ja maajoukkueista yksittäisiin seuroihin.", "title": "Urheiluvisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Lajista seuraan", "p": ["Kokoelma kattaa jääkiekon, jalkapallon, Formula 1:n, tenniksen, golfin, yleisurheilun ja rallin. Osa visoista käsittelee kokonaista lajia, osa yhtä seuraa tai maajoukkuetta.", "Seuravisoissa jokainen kortti kantaa joukkueen omat värit — Arsenal punaisena, Brasilia keltaisena. Se on pieni yksityiskohta, mutta tekee selaamisesta nopeampaa."]}, {"h": "Miksi urheilu sopii visaan", "p": ["Urheilu on yksi harvoista aiheista, joissa lähes jokaisella on jokin muistikuva: se yksi finaali, se yksi maali, se yksi kausi. Visa herättää ne muistikuvat ja testaa samalla, pitivätkö ne paikkansa.", "Kysymykset painottuvat merkittäviin hetkiin ja pysyviin faktoihin, eivät kuluvan kauden tilastoihin. Siksi visat eivät vanhene viikossa."]}, {"h": "Kolme tapaa pelata", "p": ["Urheiluvisoja voi pelata klassisena monivalintana, mutta myös Kumpi?-pelinä ja Järjestä oikein -pelinä, joissa vastataan vertailemalla eikä muistamalla ulkoa.", "Sama tieto siis palvelee montaa pelitapaa. Jos monivalinta alkaa tuntua tutulta, vaihda muotoa."]}], "faq": [{"q": "Mitä lajeja kokoelmassa on?", "a": "Jääkiekko, jalkapallo, Formula 1, tennis, golf, yleisurheilu ja ralli, sekä yksittäisiä visoja muista lajeista."}, {"q": "Käsitelläänkö vain suomalaista urheilua?", "a": "Ei. Mukana on sekä suomalaisia maajoukkueita ja urheilijoita että kansainvälisiä seuroja ja sarjoja."}, {"q": "Vanhenevatko urheiluvisat?", "a": "Kysymykset keskittyvät pysyviin faktoihin ja historiallisiin hetkiin kuluvan kauden tilastojen sijaan, joten ne pysyvät ajankohtaisina."}, {"q": "Voiko urheiluvisoja pelata muuten kuin monivalintana?", "a": "Voi. Urheilu on mukana sekä Kumpi?- että Järjestä oikein -peleissä."}]}'::jsonb),
('musiikki','collection','Musiikki','Musiikkivisat — suomalaiset artistit, bändit ja festarit','Iskelmästä metalliin ja Euroviisuista festareihin. Testaa musiikkitietosi ilmaisilla visoilla suomalaisista ja kansainvälisistä artisteista.','{"intro": "Biisi jäi päähän, mutta muistatko kuka sen teki ja milloin? Musiikkikokoelmassa on visoja yksittäisistä artisteista, bändeistä ja koko suomalaisen musiikin kirjosta iskelmästä hiphopiin.", "title": "Musiikkivisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Suomi ja maailma", "p": ["Kokoelma jakautuu karkeasti kahtia: suomalaisiin artisteihin ja kansainvälisiin nimiin. Suomalainen puoli on selvästi laajempi, ja se on tarkoituksellista — kotimainen musiikki on aihe, josta suomalaisilla on aitoa tietoa.", "Mukana on sekä nykyartisteja että nimiä, joiden ura alkoi vuosikymmeniä sitten. Sukupolvien väliset erot näkyvät tuloksissa selvästi."]}, {"h": "Artistivisa vai ilmiövisa", "p": ["Osa visoista keskittyy yhteen artistiin tai bändiin: uraan, levyihin, kokoonpanoon ja taustoihin. Osa käsittelee laajempaa ilmiötä, kuten festarikesää tai Euroviisuja.", "Artistivisat sopivat faneille, ilmiövisat kaikille. Molemmissa on sama rakenne: kymmenen kysymystä ja taustafakta jokaisen jälkeen."]}, {"h": "Festarikesä omana kautenaan", "p": ["Kesäisin musiikkikokoelma saa oman kausinostonsa. Festariaiheiset visat kokoavat yhteen esiintyjät, lavat ja ne biisit, jotka kuullaan joka kesä uudelleen.", "Kausiteemat eivät katoa kauden jälkeen — ne sulautuvat takaisin musiikkikokoelmaan."]}], "faq": [{"q": "Onko kokoelmassa vain suomalaista musiikkia?", "a": "Ei, mutta suomalainen musiikki painottuu. Mukana on myös kansainvälisiä artisteja ja bändejä."}, {"q": "Mitä musiikkilajeja visat kattavat?", "a": "Iskelmästä ja popista rockiin, metalliin ja hiphopiin. Kokoelma ei rajaudu yhteen genreen."}, {"q": "Tarvitseeko musiikkivisassa tunnistaa biisejä äänestä?", "a": "Ei. Kysymykset ovat tekstimuotoisia monivalintoja, joten visan voi pelata myös ilman ääntä."}, {"q": "Kuinka monta kysymystä musiikkivisassa on?", "a": "Useimmissa kymmenen, muutamassa viisi. Kysymysmäärä näkyy aina visan kortissa."}]}'::jsonb),
('elokuvat','collection','Elokuvat','Elokuvavisat — klassikot, kotimaiset ja blockbusterit','Kummisedästä kotimaisiin klassikoihin. Testaa elokuvatietosi ilmaisilla visoilla — kymmenen kysymystä, neljä vaihtoehtoa, ei rekisteröitymistä.','{"intro": "Elokuvan on nähnyt, repliikit muistaa, mutta entä ohjaaja, vuosiluku ja se mitä kulissien takana tapahtui? Elokuvakokoelmassa on visoja valkokankaan klassikoista ja niistä elokuvista, joita ei aina myönnetä katsotuiksi.", "title": "Elokuvavisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Klassikot ja uutuudet", "p": ["Kokoelmassa on sekä elokuvahistorian arvostetuimpia teoksia että tuoreempia hittejä. Klassikkovisat kysyvät usein taustoista ja tekijöistä, uutuusvisat juonesta ja henkilöistä.", "Kotimaiset elokuvat ovat oma ryhmänsä. Niissä kysymykset osuvat usein siihen, mitä elokuva merkitsi Suomessa — ei pelkästään siihen mitä ruudulla näkyi."]}, {"h": "Yhden elokuvan visa", "p": ["Useimmat elokuvavisat käsittelevät yhtä elokuvaa tai elokuvasarjaa kerrallaan. Se tekee niistä sopivia faneille: kymmenen kysymystä yhdestä teoksesta menee pintaa syvemmälle.", "Vastauksen jälkeen näytettävä taustafakta kertoo usein jotain, mitä ei elokuvasta itsestään näe — kuvauksista, vastaanotosta tai tekijöistä."]}, {"h": "Elokuvat ja tunnetut henkilöt", "p": ["Elokuvakokoelma ja Tunnetut henkilöt -kokoelma menevät osittain päällekkäin: sama näyttelijä voi esiintyä sekä elokuvavisassa että omassa henkilövisassaan.", "Jos jokin näyttelijä jäi kiinnostamaan, häntä kannattaa etsiä henkilökokoelmasta."]}], "faq": [{"q": "Käsittelevätkö visat yhtä elokuvaa kerrallaan?", "a": "Useimmat kyllä. Yksi visa keskittyy tyypillisesti yhteen elokuvaan tai elokuvasarjaan."}, {"q": "Löytyykö kotimaisia elokuvia?", "a": "Kyllä, kotimaiset klassikot ovat kokoelmassa omana ryhmänään kansainvälisten rinnalla."}, {"q": "Sisältävätkö visat juonipaljastuksia?", "a": "Kysymykset voivat käsitellä elokuvan tapahtumia, joten visa kannattaa pelata vasta elokuvan nähtyään."}, {"q": "Onko elokuvavisoissa kuvakysymyksiä?", "a": "Elokuvakokoelman visat ovat tekstimuotoisia. Kuvatunnistusta varten on oma Kuvavisat-kokoelmansa."}]}'::jsonb),
('matkakohteet','collection','Matkakohteet','Matkailu- ja maantiedon visat — kaupungit, järvet ja vuoret','Roomasta Tallinnaan ja Suomen järvistä maailman korkeimpiin vuoriin. Testaa maantieteen tietosi ilmaisilla visoilla, joissa on myös aiheoppaat.','{"intro": "Matkakohde on käyty läpi kartalla ja ehkä paikan päälläkin, mutta kuinka hyvin sen tuntee? Tämä kokoelma yhdistää matkailun ja maantiedon: kaupungit, luonnonihmeet ja ne mittasuhteet, jotka yllättävät.", "title": "Matkakohdevisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Kaupungit ja kohteet", "p": ["Kaupunkivisat käsittelevät yhtä kohdetta kerrallaan: historiaa, nähtävyyksiä ja niitä yksityiskohtia, jotka jäävät matkaoppaan ulkopuolelle. Mukana on sekä lähikohteita että kaukaisempia klassikoita.", "Kaupunkivisat sopivat hyvin matkan alle: ne kertovat kohteesta enemmän kuin ehtii lukea lentokentällä."]}, {"h": "Suomi ja maailma mittatikulla", "p": ["Osa visoista vertailee: suurimmat järvet, pisimmät joet, korkeimmat vuoret, kylmimmät kolkat. Näissä yllätys tulee usein mittasuhteista — moni arvaa oikean vastauksen väärin juuri kertaluokan takia.", "Suomi on kokoelmassa vahvasti mukana. Järvet, joet ja metsät ovat aiheita, joista suomalainen luulee tietävänsä enemmän kuin tietää."]}, {"h": "Aiheoppaat kokeilussa", "p": ["Osassa matkakohdevisoista on visan alla laajempi aiheopas: taustaa, usein kysyttyä ja lähteet. Se on tarkoitettu luettavaksi joko ennen peliä tai sen jälkeen.", "Aiheoppaat ovat lähteistettyjä ja päivättyjä, joten niistä näkee mihin tieto perustuu ja milloin se on tarkistettu."]}], "faq": [{"q": "Mitä matkakohteita visat käsittelevät?", "a": "Sekä yksittäisiä kaupunkeja että laajempia maantieteellisiä aiheita, kuten järviä, jokia, vuoria ja ilmastoa."}, {"q": "Onko kokoelmassa Suomea käsitteleviä visoja?", "a": "On, useita. Suomen järvet, joet ja metsät ovat omia visojaan."}, {"q": "Mikä on aiheopas?", "a": "Osan visoista alla on artikkeli, joka kertoo aiheesta taustaa ja vastaa usein kysyttyihin kysymyksiin. Siinä on myös lähteet ja tarkistuspäivä."}, {"q": "Voiko matkakohteita pelata muissa pelimuodoissa?", "a": "Voi. Maantieteelliset aiheet ovat mukana sekä Kumpi?- että Järjestä oikein -peleissä."}]}'::jsonb),
('tunnetut-henkilot','collection','Tunnetut henkilöt','Henkilövisat — näyttelijät, artistit ja urheilijat','Kuinka hyvin tunnet tutut kasvot? Satoja henkilövisoja näyttelijöistä, artisteista, urheilijoista ja poliitikoista. Viisi kysymystä per visa, ilmaiseksi.','{"intro": "Nimi on tuttu ja kasvot tunnistaa, mutta mitä hänestä oikeastaan tietää? Tämä on Tietoniekan laajin kokoelma: satoja lyhyitä visoja yksittäisistä ihmisistä, näyttelijöistä ja artisteista urheilijoihin ja poliitikkoihin.", "title": "Henkilövisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Viisi kysymystä, yksi ihminen", "p": ["Jokaisessa henkilövisassa on viisi kysymystä. Se on tarkoituksellisesti lyhyempi kuin muissa kokoelmissa: yhdestä ihmisestä ei kannata venyttää kymmentä kysymystä, jos viisi kertoo olennaisen.", "Lyhyys tekee henkilövisoista sopivia peräkkäin pelattaviksi. Moni päätyy pelaamaan niitä useamman kerralla."]}, {"h": "Keitä täältä löytyy", "p": ["Kokoelma on jaettu ammatin mukaan: näyttelijät, artistit, urheilijat, poliitikot ja historian henkilöt. Mukana on sekä suomalaisia että kansainvälisiä nimiä.", "Kortissa näkyy henkilön tarkka ammatti — jääkiekkoilija, rap-artisti, F1-kuljettaja — eikä pelkkä yleisluokka. Se auttaa löytämään juuri sen tyyppiset ihmiset, jotka kiinnostavat."]}, {"h": "Päivän sankari", "p": ["Etusivun Päivän sankari poimitaan tästä kokoelmasta: joka päivä nostetaan esiin henkilö, jolla on syntymäpäivä. Se on syy palata sivustolle päivittäin.", "Kokoelmasta voi myös selata, kenellä on syntymäpäivä tänään ja lähipäivinä."]}], "faq": [{"q": "Kuinka monta kysymystä henkilövisassa on?", "a": "Viisi. Henkilövisat ovat tarkoituksella lyhyempiä kuin muut visat."}, {"q": "Keitä henkilövisoissa käsitellään?", "a": "Näyttelijöitä, artisteja, urheilijoita, poliitikkoja ja historian henkilöitä, sekä suomalaisia että kansainvälisiä."}, {"q": "Mikä on Päivän sankari?", "a": "Päivittäin vaihtuva nosto henkilöstä, jolla on kyseisenä päivänä syntymäpäivä. Se näkyy etusivulla."}, {"q": "Tuleeko kokoelmaan uusia henkilöitä?", "a": "Kyllä, henkilökokoelma kasvaa jatkuvasti."}]}'::jsonb),
('yleistieto','collection','Yleistieto','Yleistietovisat — historia, kulttuuri, ruoka ja politiikka','Yleistietoa laidasta laitaan: historiaa, kulttuuria, ruokaa ja politiikkaa. Testaa tietosi ilmaisilla visoilla ilman rekisteröitymistä.','{"intro": "Yleistieto on se kokoelma, johon kuuluu kaikki mikä ei mahdu muualle — ja juuri siksi se on monipuolisin. Historiaa, kulttuuria, politiikkaa, ruokaa ja muotia samassa paketissa.", "title": "Yleistietovisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Laidasta laitaan", "p": ["Kokoelmassa on visoja historiasta, kulttuurista ja politiikasta sekä kevyemmistä aiheista kuten ruoasta, juomasta ja muodista. Yhteistä niille on, että ne eivät muodosta omaa syvää maailmaansa mutta ovat yksittäisinä kiinnostavia.", "Tämä tekee yleistiedosta hyvän valinnan silloin kun ei etsi mitään tiettyä. Seuraava visa on todennäköisesti eri aiheesta kuin edellinen."]}, {"h": "Miksi laaja kokoelma on hyödyllinen", "p": ["Aihekohtaiset kokoelmat palkitsevat sitä, joka tietää yhdestä asiasta paljon. Yleistieto palkitsee sitä, joka tietää monesta asiasta vähän — ja se on eri taito.", "Pubivisan tai perhepelin kysymyksiä etsivälle yleistieto on luontevin lähtökohta, koska aiheet vaihtelevat kysymyksestä toiseen."]}, {"h": "Museoista ja politiikasta", "p": ["Kulttuuriosastolla käsitellään museoita, festivaaleja ja kansallispuistoja. Politiikan puolella on sekä instituutioita että yksittäisiä poliitikkoja käsitteleviä visoja.", "Historiavisat kattavat sekä Suomen että maailman historiaa, painottuen tapahtumiin joita kouluopetuksessa käsitellään."]}], "faq": [{"q": "Mitä aiheita yleistietovisoissa on?", "a": "Historiaa, kulttuuria, politiikkaa, ruokaa ja juomaa sekä muotia ja designia."}, {"q": "Kuinka vaikeita yleistietovisat ovat?", "a": "Vaikeustaso vaihtelee visoittain. Vaikeimmat on merkitty omalla merkinnällään kortissa."}, {"q": "Sopivatko visat pubivisan kysymyksiksi?", "a": "Yleistietovisat sopivat siihen hyvin, koska aiheet vaihtelevat ja kysymyksissä on aina taustafakta."}, {"q": "Kuinka monta kysymystä yleistietovisassa on?", "a": "Useimmissa kymmenen, osassa viisi. Määrä näkyy visan kortissa."}]}'::jsonb),
('kuvavisat','collection','Kuvavisat','Kuvavisat — tunnista liput, vaakunat, eläimet ja kasvit','Yksi kuva, neljä vaihtoehtoa. Tunnista maiden liput, suomalaiset vaakunat, eläimet, linnut ja kasvit. Ilmainen kuvatunnistusvisa ilman rekisteröitymistä.','{"intro": "Kuvavisassa ei lueta kysymystä vaan katsotaan. Näet yhden kuvan ja neljä vaihtoehtoa: lipun, vaakunan, eläimen tai kasvin. Se on nopein tapa huomata, kuinka tarkka silmä oikeasti on.", "title": "Kuvavisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Kortistot", "p": ["Kuvavisat on jaettu kortistoihin aiheen mukaan: liput, vaakunat, eläimet, linnut ja kasvit. Jokainen kortisto on oma pelinsä, ja voit valita aloitatko helpoimmasta vai vaikeimmasta.", "Liput ovat useimmille tutuin lähtökohta. Suomalaiset kunnanvaakunat ovat selvästi vaikeampi kortisto — harva tunnistaa oman kotikuntansakaan."]}, {"h": "Miksi kuva on eri asia kuin kysymys", "p": ["Tekstimuotoisessa visassa oikean vastauksen voi joskus päätellä vaihtoehdoista. Kuvavisassa se onnistuu harvemmin: joko tunnistat kuvan tai et.", "Siksi kuvavisat tuntuvat armottomammilta mutta myös palkitsevammilta. Tunnistaminen on välitöntä eikä vaadi muistelua."]}, {"h": "Luonto lähikuvassa", "p": ["Eläin-, lintu- ja kasvikortistot testaavat lajintuntemusta. Ne sopivat erityisen hyvin niille, jotka liikkuvat luonnossa ja luulevat tunnistavansa lähimetsänsä lajit.", "Kortistot kasvavat sitä mukaa kun uusia kuvia lisätään."]}], "faq": [{"q": "Mitä kuvavisoja on tarjolla?", "a": "Liput, vaakunat, eläimet, linnut ja kasvit. Kortistoja lisätään ajan myötä."}, {"q": "Miten kuvavisa toimii?", "a": "Näet yhden kuvan ja neljä vaihtoehtoa. Valitset oikean, ja saat heti tietää menikö oikein."}, {"q": "Ovatko vaakunavisat suomalaisista kunnista?", "a": "Kyllä, vaakunakortisto koostuu suomalaisista kunnanvaakunoista."}, {"q": "Tarvitseeko kuvavisaan kirjautua?", "a": "Ei. Kuten kaikki Tietoniekan visat, kuvavisat ovat ilmaisia eivätkä vaadi käyttäjätiliä."}]}'::jsonb),
('ruokajuoma','collection','Ruoka & juoma','Ruoka- ja juomavisat — keittiöt, reseptit ja juomat','Kotiruoasta Michelin-tähtiin ja kahvista viiniin. Testaa ruokatietosi ilmaisilla visoilla keittiöistä, raaka-aineista ja juomakulttuurista.','{"intro": "Ruoka on aihe, josta lähes jokaisella on mielipide mutta harvemmalla faktoja. Nämä visat käsittelevät keittiöitä, raaka-aineita ja juomakulttuuria kotiruoasta ravintolamaailmaan.", "title": "Ruoka- ja juomavisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Keittiöstä toiseen", "p": ["Visat käsittelevät sekä suomalaista ruokaperinnettä että kansainvälisiä keittiöitä. Mukana on raaka-aineita, ruokalajeja ja niiden alkuperää koskevia kysymyksiä.", "Moni ruokafakta on yllättävän kiistanalainen: sama ruokalaji voi olla kotoisin useammasta maasta riippuen siitä, keneltä kysyy. Kysymyksissä pitäydytään dokumentoiduissa lähtökohdissa."]}, {"h": "Juomat omana aiheenaan", "p": ["Kahvi, tee, olut ja viini ovat omia aihepiirejään. Suomalaisia kiinnostaa erityisesti kahvi, mistä on hyvä syy: kulutuksella mitattuna Suomi on maailman kärkeä.", "Juomavisoissa kysytään sekä valmistuksesta että kulttuurista — mistä juoma tulee, miten se tehdään ja miksi sitä juodaan juuri niin kuin juodaan."]}, {"h": "Osa Yleistietoa", "p": ["Ruoka ja juoma on tietoisesti kevyempi kokoelma. Sen visat ovat myös osa Yleistieto-kokoelmaa, jossa ne sekoittuvat muiden aiheiden joukkoon.", "Jos etsit nimenomaan ruoka-aiheisia visoja, tämä sivu on oikea paikka. Jos haluat vaihtelua, kokeile Yleistietoa."]}], "faq": [{"q": "Mitä ruokavisat käsittelevät?", "a": "Keittiöitä, ruokalajeja, raaka-aineita ja juomia sekä kotimaisesta että kansainvälisestä näkökulmasta."}, {"q": "Onko mukana suomalaista ruokakulttuuria?", "a": "On. Suomalainen ruokaperinne on yksi kokoelman aiheista."}, {"q": "Kuuluvatko ruokavisat johonkin muuhun kokoelmaan?", "a": "Kyllä, ne ovat osa laajempaa Yleistieto-kokoelmaa."}, {"q": "Kasvaako kokoelma?", "a": "Kyllä, uusia ruoka- ja juoma-aiheisia visoja lisätään muun sisällön ohessa."}]}'::jsonb),
('luonnonihmeet','collection','Luonnon ihmeet','Luontovisat — eläimet, kasvit ja luonnonilmiöt','Lähimetsästä revontuliin. Testaa luontotietosi ilmaisilla visoilla eläimistä, kasveista ja luonnonilmiöistä. Kymmenen kysymystä, ei rekisteröitymistä.','{"intro": "Suomalainen liikkuu luonnossa paljon mutta tunnistaa siitä yllättävän vähän. Nämä visat käsittelevät eläimiä, kasveja ja luonnonilmiöitä lähimetsästä revontuliin.", "title": "Luontovisat pähkinänkuoressa", "last_reviewed": "2026-08-02", "sections": [{"h": "Lajit ja elinympäristöt", "p": ["Visat käsittelevät sekä yksittäisiä lajeja että kokonaisia elinympäristöjä. Suomen metsät, suot ja vesistöt ovat toistuvia aiheita, samoin niissä elävät lajit.", "Uhanalaiset ja palautuneet lajit ovat oma kiinnostava ryhmänsä: moni laji, jota pidetään harvinaisena, on itse asiassa runsastunut viime vuosikymmeninä."]}, {"h": "Ilmiöt joita kaikki näkevät", "p": ["Revontulet, yötön yö, kaamos ja vuodenaikojen vaihtelu ovat suomalaisille arkisia mutta selittyvät ilmiöillä, joita harva osaa kuvata tarkasti.", "Näissä visoissa selitysteksti tekee usein enemmän kuin kysymys: se kertoo miksi ilmiö tapahtuu, ei vain että se tapahtuu."]}, {"h": "Osa Matkakohteita", "p": ["Luonnon ihmeet on Matkakohteet-kokoelman alaosasto. Sama sisältö palvelee sekä luonnosta että matkailusta kiinnostunutta.", "Jos haluat laajemman valikoiman maantieteellisiä aiheita, siirry Matkakohteet-kokoelmaan."]}], "faq": [{"q": "Mitä luontovisat käsittelevät?", "a": "Eläimiä, kasveja, elinympäristöjä ja luonnonilmiöitä, painottuen Suomen luontoon."}, {"q": "Onko mukana lajintunnistusta kuvista?", "a": "Tämän kokoelman visat ovat tekstimuotoisia. Kuvista tunnistamista varten on Kuvavisat-kokoelma, jossa on eläin-, lintu- ja kasvikortistot."}, {"q": "Mihin kokoelmaan luontovisat kuuluvat?", "a": "Ne ovat osa Matkakohteet-kokoelmaa, jossa maantiede ja luonto kulkevat yhdessä."}, {"q": "Sopivatko visat lapsille?", "a": "Luontovisat ovat aiheiltaan neutraaleja ja sopivat myös nuoremmille pelaajille, vaikka osa kysymyksistä on haastavia."}]}'::jsonb),
('kumpi','mode','Kumpi?','Kumpi? — kaksi vaihtoehtoa, vain toinen on oikein','Kumpi järvi on suurempi? Kumpi heistä on vanhempi? Nopea vertailupeli, jossa vastataan päättelemällä eikä ulkoa muistamalla. Ilmainen, ei rekisteröitymistä.','{"intro": "Kumpi? on Tietoniekan nopein pelimuoto. Saat kaksi vaihtoehtoa ja yhden kysymyksen — kumpi on suurempi, vanhempi, pidempi tai kauempana. Toinen on oikein, ja putki jatkuu niin kauan kuin osut.", "title": "Näin Kumpi? toimii", "last_reviewed": "2026-08-02", "sections": [{"h": "Vertailu, ei ulkoa muistaminen", "p": ["Monivalintavisassa joko tiedät vastauksen tai et. Kumpi?-pelissä pärjää myös päättelemällä: vaikka et tietäisi kummankaan järven tarkkaa pinta-alaa, voit tietää kumpi niistä on suurempi.", "Siksi peli tuntuu helpommalta kuin se on. Vaikeus kasvaa, kun vaihtoehdot ovat lähellä toisiaan."]}, {"h": "Mistä kysymykset syntyvät", "p": ["Kysymyksiä ei kirjoiteta yksitellen. Ne lasketaan faktapankista, jossa on entiteettejä — ihmisiä, paikkoja, eläimiä — ja niiden mitattavia ominaisuuksia.", "Kun pankkiin lisätään uusi henkilö tai paikka, siitä syntyy automaattisesti uusia vertailuja kaikkia muita vastaan. Siksi peli ei lopu kesken."]}, {"h": "Teemat", "p": ["Voit pelata sekoituksella tai valita teeman: ihmiset, Suomi, maantieto, luonto tai historia. Sekoitus arpoo kysymykset kaikista teemoista.", "Ihmiset on laajin teema, koska henkilödataa on eniten. Jos haluat pelata pidempään ilman toistoa, se on hyvä valinta."]}], "faq": [{"q": "Miten Kumpi?-peli toimii?", "a": "Näet kaksi vaihtoehtoa ja yhden vertailukysymyksen. Valitset kumman uskot olevan oikein, ja peli jatkuu niin kauan kuin vastaat oikein."}, {"q": "Mitä teemoja Kumpi?-pelissä on?", "a": "Sekoitus, ihmiset, Suomi, maantieto, luonto ja historia."}, {"q": "Loppuvatko kysymykset kesken?", "a": "Eivät käytännössä. Kysymykset lasketaan faktapankista, joten vertailujen määrä kasvaa nopeasti aina kun pankkiin lisätään uutta tietoa."}, {"q": "Tarvitseeko peliin kirjautua?", "a": "Ei. Kumpi? on ilmainen eikä vaadi käyttäjätiliä."}]}'::jsonb),
('jarjesta','mode','Järjestä oikein','Järjestä oikein — viisi asiaa, yksi oikea järjestys','Järjestä järvet, kaupungit ja tapahtumat oikeaan järjestykseen. Vaikeampi kuin Kumpi?, koska yksi väärä paikka riittää. Ilmainen peli ilman rekisteröitymistä.','{"intro": "Järjestä oikein on Kumpi?-pelin isoveli. Kahden vaihtoehdon sijaan saat viisi, ja ne pitää asettaa oikeaan järjestykseen — suurimmasta pienimpään, vanhimmasta nuorimpaan tai päinvastoin.", "title": "Näin Järjestä oikein toimii", "last_reviewed": "2026-08-02", "sections": [{"h": "Viisi kerrallaan", "p": ["Jokaisessa kierroksessa on viisi asiaa, jotka raahataan oikeaan järjestykseen. Lopuksi näet, montako niistä osui oikealle paikalle.", "Ero Kumpi?-peliin on suurempi kuin miltä kuulostaa. Kahden vaihtoehdon vertailu on yksi päätös; viiden järjestäminen on kymmenen vertailua kerralla."]}, {"h": "Suunta vaihtelee", "p": ["Järjestys ei ole aina sama: joskus suurimmasta pienimpään, joskus toisin päin. Suunta kerrotaan aina kierroksen alussa, ja se kannattaa lukea.", "Tämä on pelin tavallisin virhelähde. Oikea järjestys väärään suuntaan tuottaa nolla pistettä."]}, {"h": "Sama tieto kuin Kumpi?-pelissä", "p": ["Järjestä oikein käyttää samaa faktapankkia kuin Kumpi?. Vertailukelpoiset ominaisuudet — pinta-ala, pituus, korkeus, vuosiluku — toimivat molemmissa peleissä.", "Jos Kumpi? alkaa tuntua helpolta, tämä on luonteva seuraava askel samasta aineistosta."]}], "faq": [{"q": "Montako asiaa pitää järjestää?", "a": "Viisi kerrallaan."}, {"q": "Mihin järjestykseen asiat laitetaan?", "a": "Suunta vaihtelee kierroksittain ja kerrotaan aina kierroksen alussa — joskus suurimmasta pienimpään, joskus päinvastoin."}, {"q": "Miten peliä pelataan puhelimella?", "a": "Asiat raahataan sormella oikeaan järjestykseen. Järjestystä voi myös muuttaa nuolipainikkeilla."}, {"q": "Mitä eroa on Kumpi?-pelillä ja Järjestä oikein -pelillä?", "a": "Kumpi?-pelissä vertaillaan kahta vaihtoehtoa, Järjestä oikein -pelissä viittä. Molemmat käyttävät samaa faktapankkia."}]}'::jsonb)
